   301  static inline void * CC_HINT(hot) fr_dcursor_set_current(fr_dcursor_t *cursor, void *item)
   302  {
   303          if (!cursor || fr_dlist_empty(cursor->dlist)) return NULL;
   304          if (!item) return NULL;
   305
   306          cursor->current = item;
   307          cursor->prev = fr_dlist_prev(cursor->dlist, item);
   308
   309          return cursor->current;
   310  }
   311
   312  /** Insert a single item at the start of the list
   313   *
   314   * @note Will not advance cursor position to r attribute, but will set cursor
   315   *       to this attribute, if it's the head one in the list.
   316   *
   317   * Insert a void at the start of the list.
   318   *
   319   * @param cursor to operate on.
   320   * @param v to insert.
   321   *
   322   * @hidecallergraph
   323   */
   324  static inline void CC_HINT(hot) fr_dcursor_prepend(fr_dcursor_t *cursor, void *v)
   325  {
   326  #ifndef TALLOC_GET_TYPE_ABORT_NOOP
   327          if (cursor->dlist->type) _talloc_get_type_abort(v, cursor->dlist->type, __location__);
   328  #endif
   329
   330          /*
   331           *      Insert at the head of the list
   332           */
   333          fr_dlist_insert_head(cursor->dlist, v);
   334
   335          /*
   336           *      Set previous if the cursor was already set but not
   337           *      prev - this will be if there was only one item in the
   338           *      list
   339           */
   340          if (cursor->current && !cursor->prev) {
   341                  cursor->prev = v;
   342          }
   343  }
   344
   345  /** Insert a single item at the end of the list
   346   *
   347   * @note Does not change the current pointer.
   348   *
   349   * @param[in] cursor to operate on.
   350   * @param[in] v to insert.
   351   *
   352   * @hidecallergraph
   353   */
   354  static inline void CC_HINT(hot) fr_dcursor_append(fr_dcursor_t *cursor, void *v)
   355  {
   356  #ifndef TALLOC_GET_TYPE_ABORT_NOOP
   357          if (cursor->dlist->type) _talloc_get_type_abort(v, cursor->dlist->type, __location__);
   358  #endif
   359
   360          fr_dlist_insert_tail(cursor->dlist, v);
   361  }
   362
   363  /** Insert directly after the current item
   364   *
   365   * @note Does not change the current pointer.
   366   *
   367   * @param[in] cursor    to operate on.
   368   * @param[in] v         Item to insert.
   369   *
   370   * @hidecallergraph
   371   */
   372  static inline void fr_dcursor_insert(fr_dcursor_t *cursor, void *v)
   373  {
   374  #ifndef TALLOC_GET_TYPE_ABORT_NOOP
   375          if (cursor->dlist->type) _talloc_get_type_abort(v, cursor->dlist->type, __location__);
   376  #endif
   377
   378          if (!cursor->current) {
   379                  fr_dcursor_append(cursor, v);
   380                  return;
   381          }
   382          fr_dlist_insert_after(cursor->dlist, cursor->current, v);
   383  }
   384
   385  /** Remove the current item
   386   *
   387   * The current item will be set to the one after the item
   388   * being removed. An example check and remove loop:
   389   *
   390   @code {.c}
   391     for (v = fr_dcursor_init(&cursor, head);
   392          v;
   393          v = fr_dcursor_current(&cursor) {
   394          if (<condition>) {
   395              v = fr_dcursor_remove(&cursor);
   396              talloc_free(v);
   397              continue;
   398          }
   399          v = fr_dcursor_next(&cursor);
   400     }
   401   @endcode
   402   *
   403   * @param[in] cursor to remove the current item from.
   404   * @return
   405   *      - item we just removed.
   406   *      - NULL on error.
   407   *
   408   * @hidecallergraph
   409   */
   410  static inline void * CC_HINT(hot) fr_dcursor_remove(fr_dcursor_t *cursor)
   411  {
   412          void *v, *p;
   413
   414          if (!cursor->current) return NULL;                      /* don't do anything fancy, it's just a noop */
   415
   416          v = cursor->current;
   417          p = fr_dcursor_list_prev_peek(cursor);
   418          fr_dlist_remove(cursor->dlist, v);
   419
   420          if (fr_dlist_head(cursor->dlist) == v) {
   421                  cursor->current = NULL;
   422                  cursor->prev = NULL;
   423          } else {
   424                  cursor->current = p;
   425                  cursor->prev = p;
   426          }
   427
   428          /*
   429           *      Advance the cursor to the next item after the one which we just removed.
   430           */
   431          cursor->current = dcursor_next(cursor, cursor->current);
   432          return v;
   433  }
   434
   435  /** Moves items from one cursor to another.
   436   *
   437   * Move multiple items from one cursor to another.
   438   *
   439   * @note Will only move items from the current position of to_append
   440   *      up to the end of to_append. Items will be removed from the original
   441   *      cursor.  Items will be inserted after the current position of the
   442   *      destination cursor (which will not be changed).
   443   *
   444   * @param[in] cursor            to operate on.
   445   * @param[in] to_append         Items to append.
   446   *
   447   * @hidecallergraph
   448   */
   449  static inline void fr_dcursor_merge(fr_dcursor_t *cursor, fr_dcursor_t *to_append)
   450  {
   451          void            *v, *p;
   452
   453          p = cursor->current;
   454          while ((v = fr_dcursor_remove(to_append))) {
   455                  fr_dcursor_insert(cursor, v);
   456                  cursor->current = v;
   457          }
   458          cursor->current = p;
   459  }
   460
   461  /** Return the next item, skipping the current item, that satisfies an evaluation function.
   462   *
   463   * @param[in] cursor    to operate on
   464   * @param[in] eval      evaluation function
   465   * @param[in] uctx      context for the evaluation function
   466   * @return the next item satisfying eval, or NULL if no such item exists
   467   *
   468   * @hidecallergraph
   469   */
   470  static inline void *fr_dcursor_filter_next(fr_dcursor_t *cursor, fr_dcursor_eval_t eval, void const *uctx)
   471  {
   472          void *item;
   473
   474          do {
   475                  item = fr_dcursor_next(cursor);
   476          } while (item && !eval(item, uctx));
   477
   478          return item;
   479  }
