   391                          default:
   392                                  want = 255;
   393                                  break;
   394
   395                          case FR_AUTHENTICATION_TYPE_VALUE_CHAP:
   396                                  want = 1 + 8 + 16; /* id + 8 octets of challenge + 16 hash */
   397                                  break;
   398
   399                          case FR_AUTHENTICATION_TYPE_VALUE_MSCHAP:
   400                                  want = 1 + 8 + 49; /* id + 8 octets of challenge + 49 MS-CHAP stuff */
   401                                  break;
   402
   403                          case FR_AUTHENTICATION_TYPE_VALUE_MSCHAPV2:
